import{_ as o,c as t,o as a,aj as r}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Type Alias: PlatformRow<TRow>","description":"","frontmatter":{},"headers":[],"relativePath":"reference/primitive-functions/api/type-aliases/PlatformRow.md","filePath":"reference/primitive-functions/api/type-aliases/PlatformRow.md"}'),d={name:"reference/primitive-functions/api/type-aliases/PlatformRow.md"};function n(s,e,i,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>primitive-functions</strong></a></p><hr><p><a href="./../globals.html">primitive-functions</a> / PlatformRow</p><h1 id="type-alias-platformrow-trow" tabindex="-1">Type Alias: PlatformRow&lt;TRow&gt; <a class="header-anchor" href="#type-alias-platformrow-trow" aria-label="Permalink to “Type Alias: PlatformRow&lt;TRow&gt;”">​</a></h1><blockquote><p><strong>PlatformRow</strong>&lt;<code>TRow</code>&gt; = <code>0</code> <em>extends</em> <code>1</code> &amp; <code>TRow</code> ? <code>TRow</code> : <code>Omit</code>&lt;<code>TRow</code>, <code>&quot;id&quot;</code>&gt; &amp; <code>object</code></p></blockquote><p>A row as the platform HANDS IT BACK: whatever the schema declared, plus the record identity the platform owns.</p><p>Every stored record has an <code>id</code>. A save that arrives without one is given a ULID, a projection always keeps it, and <code>delete</code> and <code>patch</code> take nothing else — so a function that queries a model and then moves one of its rows needs the id of the row it just read. A schema is free to say nothing about that field, and most do; the identity is the platform&#39;s, not the schema&#39;s, so it is added here rather than rendered into each declaration.</p><p>A declared <code>id</code> is REPLACED, never intersected: one declared optional would stay optional on a read row it is always present on, and one declared with some other type would intersect to <code>never</code> and be unusable. The platform stamps a string whatever the schema says.</p><p>An <code>any</code> row stays <code>any</code> — <code>DatabaseHandle&lt;any&gt;</code> is <code>defineQuery</code>&#39;s default handle, and turning its rows into an object with one known member would narrow code that was deliberately left open.</p><p>Writes are untouched: every one of them takes <code>Partial&lt;TRow&gt;</code>, so a row a function BUILDS still needs no id.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="trow" tabindex="-1">TRow <a class="header-anchor" href="#trow" aria-label="Permalink to “TRow”">​</a></h3><p><code>TRow</code></p>',13)])])}const w=o(d,[["render",n]]);export{m as __pageData,w as default};
